content.text:
[
  {
    "slug": "shimmer-button",
    "title": "Shimmer Button",
    "category": "interactive",
    "description": "A pill button with a conic-gradient highlight that travels around the border. Self-contained, themeable via props, disables motion under prefers-reduced-motion."
  },
  {
    "slug": "velocity-marquee",
    "title": "Velocity Marquee",
    "category": "text",
    "description": "An infinite marquee that accelerates with the page's scroll velocity and eases back to a base speed. Seamless two-track loop, rAF-driven, frozen under reduced-motion."
  },
  {
    "slug": "kinetic-text",
    "title": "Kinetic Text",
    "category": "text",
    "description": "Reveals text word- or char-by-char with a spring rise-and-mask as it scrolls into view. Static, fully legible fallback under reduced-motion."
  },
  {
    "slug": "magnetic-dock",
    "title": "Magnetic Dock",
    "category": "interactive",
    "description": "A macOS-style dock whose items magnify with cursor proximity, spring-smoothed. Keyboard focusable; magnify disabled under reduced-motion."
  },
  {
    "slug": "aurora-background",
    "title": "Aurora Background",
    "category": "hero",
    "description": "A GPU-cheap animated aurora of drifting radial-gradient bands with optional grain. Fills its container behind content; freezes under reduced-motion."
  },
  {
    "slug": "dot-matrix-loader",
    "title": "Dot Matrix Loader",
    "category": "loader",
    "description": "A matrix of dots choreographed purely by per-dot animation-delay math — seven variants: diagonal wave, orbit beam, boustrophedon snake, radial pulse, cascading rain, scanline sweep, and outward spiral. Accessible busy status; holds at mid-opacity under reduced-motion."
  },
  {
    "slug": "magnet-lines",
    "title": "Magnet Lines",
    "category": "effect",
    "description": "A grid of bars that rotate to point at the cursor like iron filings around a magnet. Pointer-driven, no rAF loop; holds base angle under reduced-motion."
  },
  {
    "slug": "dither-aurora",
    "title": "Dither Aurora",
    "category": "hero",
    "description": "“Prism Drift” — a WebGL ordered-dither aurora: value noise domain-warped into a slow flow, mapped onto a three-stop gradient, then quantised through a 4×4 Bayer matrix so it renders as a visible pixel lattice, not banding. Pointer parallax is spring-smoothed; renders one static frame under reduced-motion."
  },
  {
    "slug": "liquid-metal-button",
    "title": "Liquid Metal Button",
    "category": "interactive",
    "description": "A pill button ringed by a live WebGL liquid-metal shader — chromatic, silver, or gold reflections that intensify on hover. Polymorphic like Shimmer Button; the shader freezes to a single static frame under reduced-motion."
  },
  {
    "slug": "dynamic-island",
    "title": "Dynamic Island",
    "category": "interactive",
    "description": "An iOS-style black pill that spring-morphs between a compact idle pill, an expanded card, and a circular ring state, with layout-animated size and corner-radius. Works controlled or uncontrolled; collapsed it is a button (Enter/Space expand), expanded it is a dialog that Escape, its close control, or an outside click collapses, with focus handed to the panel on open and back on close. Under prefers-reduced-motion the morph is skipped and states switch instantly."
  },
  {
    "slug": "expandable-card",
    "title": "Expandable Card",
    "category": "interactive",
    "description": "A card that spring-expands in place to reveal a body whose children fade and slide in with a slight stagger, while siblings in a grid stay put. Works controlled or uncontrolled with full button/aria-expanded keyboard semantics, and expands or collapses instantly under prefers-reduced-motion."
  },
  {
    "slug": "logo-carousel",
    "title": "Logo Carousel",
    "category": "effect",
    "description": "A wall of N columns whose tiles flip through a shared pool of logos with a staggered vertical rotateX + y + fade swap — a single clock advances exactly one column per tick so two tiles never swap at once. Logos sit grayscale at 70% opacity and bloom to full colour on hover; under prefers-reduced-motion it collapses to a static grid of the first N logos with no cycling."
  },
  {
    "slug": "gravity-dots",
    "title": "Gravity Dots",
    "category": "effect",
    "description": "A canvas dot-grid field the cursor bends — dots within range are pulled in (or repelled) and spring home with damped overshoot, smearing into capsules while they move. Sleeps when settled, offscreen, or tab-hidden; renders a static grid under reduced motion."
  },
  {
    "slug": "gradient-heading",
    "title": "Gradient Heading",
    "category": "text",
    "description": "A polymorphic heading (h1–h6/p) whose text is painted with a background-clipped brand gradient in three variants and four sizes. When motion is allowed the gradient drifts on a slow ~8s ease-in-out loop; under prefers-reduced-motion or animate={false} it renders a legible static gradient with edge-defining shadow."
  },
  {
    "slug": "revenue-chart",
    "title": "Revenue Chart",
    "category": "block",
    "description": "A hand-rolled SVG area chart with a smooth monotone-cubic curve, gradient fill, and a stroke-draw + fill-fade mount animation; a crosshair tooltip snaps to the nearest point on hover or arrow-key scrub. Renders complete with no draw-in under reduced-motion."
  },
  {
    "slug": "transaction-list",
    "title": "Transaction List",
    "category": "block",
    "description": "A dashboard transaction-list block: colour-seeded initial discs, mono reference ids, tabular-nums amounts (negative red-ish / positive green-ish), and dotted completed/pending/failed status chips. Rows stagger-fade-in on mount with a spring and raise their background on hover; under reduced motion the stagger is dropped, rows render instantly, and the pending dot stops pulsing."
  },
  {
    "slug": "device-frame",
    "title": "Device Frame",
    "category": "block",
    "description": "Pure-CSS device mockups that clip children into a browser window (traffic lights, address bar, optional tab strip) or a phone (dynamic-island notch, side buttons, screen inner shadow). Hairline edges stay crisp in light and dark, and the phone scales proportionally at any width via container-query units. Fully static — no animation, so nothing to disable under reduced motion."
  },
  {
    "slug": "sign-in-slice",
    "title": "Sign-In Slice",
    "category": "block",
    "description": "A complete drop-in sign-in card: spring floating-label email input, a continue button that runs an inline progress sheen then morphs into a drawn success check + \"Check your inbox\" panel, OAuth-style buttons, and mono fine print. Real form/label/aria-live semantics; shake, sheen, and springs drop to instant swaps under reduced-motion."
  },
  {
    "slug": "sticky-scroll-cards",
    "title": "Sticky Scroll Cards",
    "category": "interactive",
    "description": "A scroll-driven card stack: each card pins at a sticky offset while the next scrolls over it, receding with a slight scale-down, dim, and blur driven by per-card useScroll/useTransform against ordinary page scroll (no hijack). Under prefers-reduced-motion the depth transforms are dropped and cards render as a plain, static, legible stack."
  },
  {
    "slug": "split-flap",
    "title": "Split Flap",
    "category": "text",
    "description": "A Solari-board split-flap text display: mono ink cells riffle through a character set with a 3D half-flap (CSS perspective + rotateX) and settle left-to-right, animating whenever the text prop changes. Under prefers-reduced-motion it renders the final text instantly with no flips."
  },
  {
    "slug": "eye-tracking",
    "title": "Eye Tracking",
    "category": "effect",
    "description": "A set of cartoon oval eyes whose pupils chase the pointer anywhere in the viewport — spring-smoothed and geometrically clamped inside each eye — with an occasional natural blink that pauses during fast pointer flicks. Under prefers-reduced-motion the pupils rest centered and the blink is disabled."
  },
  {
    "slug": "shift-card",
    "title": "Shift Card",
    "category": "interactive",
    "description": "A layered card whose front face (title + label) slides and fades up on hover or focus to reveal a detail layer beneath (body + CTA), while the whole card takes a spring-smoothed parallax tilt toward the pointer and a cursor-tracking accent glow. Renders as a link when given an href, reveals fully on keyboard focus-within with a focus-visible ring, and under prefers-reduced-motion drops the tilt and slide for a plain opacity cross-fade."
  },
  {
    "slug": "notification-stack",
    "title": "Notification Stack",
    "category": "interactive",
    "description": "An iOS-lockscreen notification pile: cards stack behind the top one with a slight y-offset and scale falloff, new items spring in from the top and dismissed ones swipe/fade out, and tapping the top card fans the stack into a full list and back. Under prefers-reduced-motion it degrades to a plain, static, fully-legible list with no stack transforms, drag, or springs."
  },
  {
    "slug": "animated-grid",
    "title": "Animated Grid",
    "category": "hero",
    "description": "A hero backdrop of hairline grid cells with a soft radial spotlight that tracks the pointer via CSS variables (no per-cell React state), plus an optional deterministic ambient cell pulse; under prefers-reduced-motion it renders a static grid with a single centered glow."
  },
  {
    "slug": "text-scramble",
    "title": "Text Scramble",
    "category": "text",
    "description": "Resolves a string out of random glyphs left-to-right, each character flickering through a short scramble tail before it locks and settles from a brand accent to the inherited color. Triggers on view, mount, or hover; renders the final text statically under reduced-motion."
  },
  {
    "slug": "text-highlighter",
    "title": "Text Highlighter",
    "category": "text",
    "description": "An inline highlighter that sweeps a marker band, drawn underline, or framed box across text left-to-right as it scrolls into view. Wraps naturally across lines and keeps the glyphs fully legible throughout; under prefers-reduced-motion the highlight is shown complete with no sweep."
  },
  {
    "slug": "animated-input",
    "title": "Animated Input",
    "category": "interactive",
    "description": "A text field with a spring floating label that rises on focus/fill, a centre-drawn accent underline, an optional tinting leading icon, and typed feedback — an error string shakes the field once, paints a live-announced red hint and sets aria-invalid, while success draws a check tick; controlled or uncontrolled with real label/id/aria-describedby wiring. Under prefers-reduced-motion every transition collapses to an instant, legible state (no shake, draw, or float tween) and the focus ring uses :focus-visible."
  },
  {
    "slug": "pricing-table",
    "title": "Pricing Table",
    "category": "block",
    "description": "A three-tier pricing block whose keyboard-operable monthly/yearly switch spring-tweens every price and lights a save badge computed from the largest annual discount; the popular tier gets an accent border, a softly pulsing glow, and a wide-screen scale-up. Under prefers-reduced-motion prices snap instantly, the knob jumps, and the glow holds a single static frame."
  },
  {
    "slug": "image-reveal",
    "title": "Image Reveal",
    "category": "effect",
    "description": "A scroll-triggered curtain wipe that uncovers an image via an animating clip-path inset, a 1.1→1 overscan, and a single diagonal sheen sweep, fired once on scroll-into-view. Under prefers-reduced-motion the image is shown immediately at full size with no wipe, scale, or sheen."
  },
  {
    "slug": "cursor-image-trail",
    "title": "Cursor Image Trail",
    "category": "effect",
    "description": "A hover region that leaves a trail of images chasing the cursor — images from a pool pop in at pointer positions (throttled by distance) and fade/scale out a moment later, driven by a single rAF loop over a recycled pool of nodes with zero per-frame React state. Under prefers-reduced-motion the trail is disabled entirely and only the children render."
  },
  {
    "slug": "drag-scroll-gallery",
    "title": "Drag Scroll Gallery",
    "category": "interactive",
    "description": "A horizontal rail you drag, flick, or wheel to scroll, with hand-written inertia, rubber-band ends, and optional flick-to-snap; items scale, tilt, and fade by distance from centre. Keyboard-navigable with role=list and focusable items, and under prefers-reduced-motion it degrades to a plain overflow-x scroller with CSS scroll-snap — no inertia or scaling."
  },
  {
    "slug": "rich-tooltip",
    "title": "Rich Tooltip",
    "category": "interactive",
    "description": "A Vercel-style rich tooltip that springs open from its trigger with a scale + fade and a real arrow, holding arbitrary ReactNode content rather than a bare string. Placement is computed by hand (no positioning lib) — measuring trigger and tooltip to auto-flip top⇄bottom / left⇄right on viewport overflow and clamp the cross axis — and it renders through a portal to document.body so ancestor overflow never clips it. Hover and focus open it with small delays, moving into the tooltip keeps it open, and Escape closes; under prefers-reduced-motion the show/hide is instant with no scale."
  },
  {
    "slug": "token-swap-card",
    "title": "Token Swap Card",
    "category": "block",
    "description": "A demo-grade crypto swap card with two token fields (searchable keyboard-driven picker + amount input) whose amounts derive from the USD price ratio, a center button that flips 180° and swaps the sides on a spring, a live rate line, and a Swap button that runs an inline pending → done animation. The flip, card cross, and spinner drop to instant state swaps under prefers-reduced-motion."
  },
  {
    "slug": "hover-member-row",
    "title": "Hover Member Row",
    "category": "interactive",
    "description": "A team roster where pointing at or keyboard-focusing a row lifts it into a rich preview — the avatar swells, an accent bar draws down the left edge, the role and bio slide open, a corner arrow eases in, and the other rows dim back. Hover and focus drive identical state (pointer wins ties); each row is a real anchor or button carrying a full aria-label so the reveal never gates assistive tech. Under prefers-reduced-motion every transform is dropped and the preview simply cross-fades in via opacity."
  },
  {
    "slug": "family-drawer",
    "title": "Family Drawer",
    "category": "interactive",
    "description": "A bottom sheet that springs up from the edge and morphs its height through a family of steps: swap the children (with an optional contentKey) and it measures the incoming content, springs the panel to fit, and cross-fades the step swap, while a grabber handle drags the sheet down to dismiss (velocity-aware). Fully modal — focus trap and return, body scroll lock, Escape and backdrop to close; under prefers-reduced-motion the height morph, slide-up, and drag physics are dropped for an instant, legible show/hide."
  },
  {
    "slug": "progress-ring",
    "title": "Progress Ring",
    "category": "block",
    "description": "A circular SVG progress ring whose rounded-cap gradient arc (violet → fuchsia) sweeps to its value by transitioning stroke-dashoffset in pure CSS over a dim track, with a centred percentage or custom label and real progressbar/aria-value semantics. Under prefers-reduced-motion the sweep is disabled and the ring draws statically at its final value."
  },
  {
    "slug": "stat-card",
    "title": "Stat Card",
    "category": "block",
    "description": "A dashboard KPI tile whose tabular-nums value counts up from zero when scrolled into view, with a signed delta chip and an optional inline sparkline."
  },
  {
    "slug": "animated-counter",
    "title": "Animated Counter",
    "category": "text",
    "description": "A number that rolls to its value odometer-style — each digit column slides vertically to its target through the digits between, with tabular-nums so the width never jitters."
  },
  {
    "slug": "avatar-stack",
    "title": "Avatar Stack",
    "category": "interactive",
    "description": "An overlapping avatar group: hovering or focusing an avatar lifts it and reveals a name tooltip while neighbours part slightly; extras collapse into a “+N” chip and images fall back to deterministic colored initials. Under reduced-motion the lift and parting are dropped; the tooltip still appears."
  },
  {
    "slug": "texture-button",
    "title": "Texture Button",
    "category": "interactive",
    "description": "A tactile button built from stacked surface layers — a gradient face, inlined grayscale noise grain, a soft top-inner sheen, and a composed inset+drop shadow that sinks on press — in accent, surface, and glass variants. The press transform is dropped under prefers-reduced-motion while the pressed colour/shadow still fires, and the focus-visible ring is an outline sitting outside the button."
  },
  {
    "slug": "border-beam",
    "title": "Border Beam",
    "category": "effect",
    "description": "Wraps content in a card whose rounded border is traced by a glowing violet-to-fuchsia comet, built from a mask-composite ring and a CSS Motion Path beam. Under prefers-reduced-motion the comet is dropped and the ring falls back to a static, legible gradient border."
  },
  {
    "slug": "intro-disclosure",
    "title": "Intro Disclosure",
    "category": "interactive",
    "description": "A first-run onboarding sequence: a stepped dialog card with title, body, optional media, Back/Next, a clickable progress-dots row, and Skip, where steps cross-fade and slide in the travel direction while the card height springs to fit the incoming content. It is a real role=\"dialog\" with focus trap, Escape-to-skip, and focus return; under prefers-reduced-motion the slide, blur, and height morph are dropped and steps swap instantly."
  },
  {
    "slug": "tweet-grid",
    "title": "Tweet Grid",
    "category": "block",
    "description": "A masonry-ish testimonial wall of tweet cards that fade and rise into view with a staggered column cascade and lift on hover, built on pure CSS multi-column layout that steps down responsively while keeping screen-reader reading order. Under prefers-reduced-motion the grid is fully static — no stagger, hover lift, or sheen — with every card legible at rest."
  },
  {
    "slug": "ai-input",
    "title": "AI Input",
    "category": "block",
    "description": "A polished AI chat composer: an auto-growing textarea, a leading model/attach control row, an empty-disabled send button that swaps to a brief pending spinner on submit, a soft focus glow, and empty-state suggestion chips that fill the field on click (Enter sends, Shift+Enter newlines). Under prefers-reduced-motion the glow pulse, spinner rotation, and chip/icon transitions resolve to instant, legible static states."
  },
  {
    "slug": "peek-carousel",
    "title": "Peek Carousel",
    "category": "interactive",
    "description": "An Apple-style peek carousel where the active slide springs to center at full scale while the previous/next slides peek in at the edges, scaled to ~0.86 and dimmed; navigate by arrows, dots, drag (with velocity-projected snap), or wheel. Under prefers-reduced-motion it degrades to a plain CSS scroll-snap scroller with no scaling or inertia, keeping the same arrows, dots, keyboard, and labelling."
  },
  {
    "slug": "parallax-hero",
    "title": "Parallax Hero",
    "category": "hero",
    "description": "A layered parallax hero where a gradient backdrop, floating accent shapes, optional mid-ground layers, and the copy slot each drift on their own depth plane from spring-smoothed pointer input, tilting a few degrees in 3D for a diorama feel; under prefers-reduced-motion the parallax and shape drift are disabled, leaving a static, legible composition."
  },
  {
    "slug": "ascii-render",
    "title": "ASCII Render",
    "category": "effect",
    "description": "A live ASCII-art field: two drifting noise octaves are sampled per cell and mapped through a brightness ramp into a monospace grid, with an optional pointer ripple. A single rAF loop pauses off-screen; the first frame is deterministic so SSR agrees, and under reduced-motion that one static frame is all that renders."
  },
  {
    "slug": "mega-navbar",
    "title": "Mega Navbar",
    "category": "block",
    "description": "A sticky, translucent top bar with an Apple-style mega-menu: hovering or keyboard-focusing a top item springs open a rich dropdown of link columns while a shared background pill glides between active items via a Motion layout animation. Collapses to a hamburger disclosure with an accordion on mobile; under prefers-reduced-motion the pill snaps instead of gliding and the sheet opens/closes instantly."
  },
  {
    "slug": "scroll-text-reveal",
    "title": "Scroll Text Reveal",
    "category": "text",
    "description": "A block of copy that illuminates word-by-word as it scrolls through the viewport — a reading highlighter driven by useScroll, each word cross-fading from muted to foreground over its own slice of scroll progress. The animated layer is aria-hidden with an intact screen-reader copy; under prefers-reduced-motion every word renders fully lit with no scroll mapping."
  },
  {
    "slug": "command-palette",
    "title": "Command Palette",
    "category": "interactive",
    "description": "A self-written ⌘K command palette (no cmdk): a body-portalled modal that substring/subsequence-filters grouped commands, with wrapping arrow-key navigation, Enter to run, focus trap and return, body-scroll lock, and a spring scale-and-fade entrance. Under prefers-reduced-motion every transition is instant and the ambient brand sheen holds still."
  },
  {
    "slug": "activity-feed",
    "title": "Activity Feed",
    "category": "block",
    "description": "A vertical activity timeline: markers on a mask-faded gradient rail, each with an actor, a highlighted action target, a relative timestamp, and optional detail; rows stagger-fade in on mount and the newest carries a soft live pulse. Under prefers-reduced-motion the feed paints once, fully legible, with no stagger, rail-draw, or pulse."
  },
  {
    "slug": "file-drop",
    "title": "File Drop",
    "category": "interactive",
    "description": "A demo drag-and-drop dropzone (no real upload) that highlights and lifts its icon on drag-over, accepts drop or click/keyboard browse via a real hidden file input, then lists chosen files as chips with a type icon, size, a fake ease-out progress bar, and a remove button; oversize files are rejected with a shake. Under prefers-reduced-motion it drops the scale, shake, and shimmer and jumps progress straight to done."
  },
  {
    "slug": "liquid-blobs",
    "title": "Liquid Blobs",
    "category": "hero",
    "description": "A gooey metaball hero backdrop: soft radial blobs drift on slow sine orbits and lean gently toward the pointer, fusing like liquid where they overlap via the SVG gooey-filter trick (a wide feGaussianBlur plus an alpha-contrast feColorMatrix). A single rAF loop writes GPU-only translate/scale, the blur radius tracks the container so the goo reads the same at any size, and an IntersectionObserver idles it off-screen; under prefers-reduced-motion the blobs settle into a static, still-merged arrangement with no drift."
  },
  {
    "slug": "hero-section",
    "title": "Hero Section",
    "category": "block",
    "description": "A complete marketing hero block — mono uppercase eyebrow, tracking-tight headline with one gradient-accented word, subcopy, primary/secondary CTA pair, and a mono stats row — that spring-staggers in on mount over two blurred radial glows drifting on slow keyframe orbits; under prefers-reduced-motion the content reveals instantly with no stagger and the glows hold a static frame."
  },
  {
    "slug": "feature-bento",
    "title": "Feature Bento",
    "category": "block",
    "description": "A bento-grid feature section whose cells span mixed footprints (wide, tall, 2x2) on a dense responsive grid, fade-rise into view with a per-cell stagger, and wake a soft accent glow that trails the pointer — written straight to CSS variables with one pointermove listener per cell and zero per-frame React state — while the border brightens on hover. Under prefers-reduced-motion the section is fully static: no stagger, no glow tracking, and the icon halo holds a single legible frame."
  },
  {
    "slug": "testimonial-marquee",
    "title": "Testimonial Marquee",
    "category": "block",
    "description": "A wall of testimonial rows scrolling infinitely in alternating directions via a seamless two-half translateX(-50%) loop; hovering a row or tabbing onto any card pauses just that row, short rows are tiled with aria-hidden passes so the track always outruns the viewport, and cards fall back to a brand-accent initials disc when no avatar is given. Under prefers-reduced-motion it collapses to a static wrapped grid with no scroll and no duplicates."
  },
  {
    "slug": "cta-banner",
    "title": "CTA Banner",
    "category": "block",
    "description": "A closing call-to-action band: an ink panel with a slow aurora gradient sweep, faint edge-masked dotted grid, and a glow that pulses behind the primary button — with an optional gradient-highlighted accent word."
  },
  {
    "slug": "faq-accordion",
    "title": "FAQ Accordion",
    "category": "block",
    "description": "An FAQ section whose question rows spring-expand to reveal answers — the panel height morphs while content fades and lifts, and a plus icon rotates into an ×. Single mode collapses siblings; multiple lets several stay open. Every row is a real button with aria-expanded/controls, answers are labelled regions, and Up/Down/Home/End rove between questions. Under reduced-motion panels open and close instantly."
  },
  {
    "slug": "stats-band",
    "title": "Stats Band",
    "category": "block",
    "description": "A horizontal strip of headline numbers that count up on scroll-in with mono captions, hairline dividers, and per-stat prefix/suffix/decimals."
  },
  {
    "slug": "section-dots",
    "title": "Section Dots",
    "category": "interactive",
    "description": "A scroll-spy side rail whose active dot stretches into a labelled pill, tracking the section in view with IntersectionObserver and smooth-scrolling on click."
  },
  {
    "slug": "squircle",
    "title": "Squircle",
    "category": "effect",
    "description": "An Apple-style superellipse (squircle) mask that clips any content to a true Lamé-curve silhouette, with an optional constant-width outline."
  },
  {
    "slug": "gooey-toggle",
    "title": "Gooey Toggle",
    "category": "interactive",
    "description": "A segmented radio toggle whose active pill travels between options with a gooey liquid stretch, rendered through an SVG goo filter with a snappy leader and a softer follower spring."
  },
  {
    "slug": "wallet-stack",
    "title": "Wallet Stack",
    "category": "interactive",
    "description": "A Family-wallet-style deck of gradient credit-card faces; click or press Enter/Space to spring the front card up and tuck it to the back while the rest advance."
  },
  {
    "slug": "theme-toggle",
    "title": "Theme Toggle",
    "category": "interactive",
    "description": "An animated sun ⇄ moon theme button: a masking circle slides in to bite the sun into a crescent while rays retract and stars twinkle in — CSS-only, controlled or uncontrolled, SSR-safe."
  },
  {
    "slug": "spotlight-card",
    "title": "Spotlight Card",
    "category": "interactive",
    "description": "A surface lit by a pointer-following spotlight — a soft radial face wash plus a mask-composited border-glow ring, both tracked through CSS custom properties written on pointermove so nothing re-renders per frame."
  },
  {
    "slug": "compare-slider",
    "title": "Compare Slider",
    "category": "interactive",
    "description": "A before/after reveal with a draggable vertical divider, click-to-jump track, and a full-keyboard ARIA slider grip; panels accept image descriptors or arbitrary nodes."
  },
  {
    "slug": "morph-tabs",
    "title": "Morph Tabs",
    "category": "interactive",
    "description": "Animated WAI-ARIA tabs whose shared pill/underline indicator springs between triggers while panels cross-fade and slide in the travel direction."
  },
  {
    "slug": "orbit-icons",
    "title": "Orbit Icons",
    "category": "effect",
    "description": "A centerpiece encircled by concentric dashed rings of evenly-spaced icon chips that revolve continuously while staying upright."
  },
  {
    "slug": "balloon-burst",
